INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(15701, 'Proverbs 11:1', 'Proverbs', 11, 1, '&nbsp;مالِک خُدائ د تلې د غلط استعمال نه نفرت کوى، خو هغه په صحيح ناپ تول خوشحاليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15702, 'Proverbs 11:2', 'Proverbs', 11, 2, '&nbsp;کله چې په انسان کښې غرور راشى نو په هغۀ رسوائى راشى، خو د عاجزۍ سره حِکمت راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15703, 'Proverbs 11:3', 'Proverbs', 11, 3, '&nbsp;د صادقانو ايماندارى د هغوئ لارښودنه کوى، خو بې‌ايمانه په خپلې بې‌ايمانۍ تباه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15704, 'Proverbs 11:4', 'Proverbs', 11, 4, '&nbsp;د عدالت په ورځ به مال دولت په کار نۀ راځى، خو صداقت به ستاسو ژوند بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15705, 'Proverbs 11:5', 'Proverbs', 11, 5, '&nbsp;د صادقانو صداقت د هغوئ لار سموى، خو بدعمله به د خپلې بدعملۍ لاندې راګېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15706, 'Proverbs 11:6', 'Proverbs', 11, 6, '&nbsp;د صادقانو صداقت هغوئ بچ کوى، خو بې‌ايمانه خپل لالچ کښې ګېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15707, 'Proverbs 11:7', 'Proverbs', 11, 7, '&nbsp;کله چې يو بدعمله مرى، د هغۀ اُميد ختم شى. هر څومره اُميدونه چې هغه د خپل مال د طاقت نه لرى هغه پناه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15708, 'Proverbs 11:8', 'Proverbs', 11, 8, '&nbsp;صادق سړے د تکليفونو نه خلاص وى، او دا تکليفونه د هغوئ په ځائ په بدعمله خلقو باندې راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15709, 'Proverbs 11:9', 'Proverbs', 11, 9, '&nbsp;په خپلو خبرو سره کافر خپل ګاونډيان تباه کوى، خو صادق به د خپل عِلم په ذريعه بچ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15710, 'Proverbs 11:10', 'Proverbs', 11, 10, '&nbsp;کله چې صادقان برکتى شى نو ټول ښار په هغوئ خوشحالى کوى، او کله چې بدعمله هلاک شى نو د خوشحالۍ چغې راوچتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15711, 'Proverbs 11:11', 'Proverbs', 11, 11, '&nbsp;د صادقانو د برکت په وجه ښار آباديږى، خو د بدعمله په خبرو هغه تباه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15712, 'Proverbs 11:12', 'Proverbs', 11, 12, '&nbsp;هغه څوک چې کم عقل وى نو خپل ګاونډى ته سپک ګورى، خو هوښيار او پوهه سړے خپله ژبه قابو کښې ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15713, 'Proverbs 11:13', 'Proverbs', 11, 13, '&nbsp;غېبت کوونکے د نورو راز خوروى، خو قابل اعتماد کس راز پټ ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15714, 'Proverbs 11:14', 'Proverbs', 11, 14, '&nbsp;خو بغېر د رهنمايۍ نه په يو قوم باندې زوال راځى، خو ډېر مشوره ورکوونکى کاميابى يقينى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15715, 'Proverbs 11:15', 'Proverbs', 11, 15, '&nbsp;کۀ چرې څوک د يو ناپېژندګلو کس ضمانت وکړى نو په يقين سره به دا کس تاوانى شى، او کۀ څوک چا ته د ضمانت لاس ورنۀ کړى نو هغه به بچ پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15716, 'Proverbs 11:16', 'Proverbs', 11, 16, '&nbsp;يوه رحمدله ښځه عزت او احترام ګټى، خو بې‌رحمه سړى مال دولت ګټى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15717, 'Proverbs 11:17', 'Proverbs', 11, 17, '&nbsp;يو رحمدله کس خپل ځان ته فائده ورکوى، خو ظالم سړے خپل ځان په تکليفونو کښې راګېروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15718, 'Proverbs 11:18', 'Proverbs', 11, 18, '&nbsp;بدکاره سړے په دوکه مال ګټى، خو هغوئ څوک چې د صداقت کرونده کوى نو حقيقى اجر به ومومى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15719, 'Proverbs 11:19', 'Proverbs', 11, 19, '&nbsp;رښتينے صادق سړے به ژوندے پاتې شى، خو هغوئ څوک چې شرارت کوى نو خپل مرګ ته روان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15720, 'Proverbs 11:20', 'Proverbs', 11, 20, '&nbsp;مالِک خُدائ د هغوئ نه نفرت کوى د چا زړونه چې کاږۀ وى، خو هغه د هغوئ سره مينه کوى د چا چال چلن چې بې‌داغه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15721, 'Proverbs 11:21', 'Proverbs', 11, 21, '&nbsp;په دې يقين وکړئ، چې بدکاران به بې‌سزا پاتې نۀ شى، خو هغوئ څوک چې صادقان دى هغوئ به آزاد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15722, 'Proverbs 11:22', 'Proverbs', 11, 22, '&nbsp;د تميز نه بغېر يوه ښُکلې ښځه داسې وى لکه د سرو زرو نتکۍ چې د خنزير په پوزه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15723, 'Proverbs 11:23', 'Proverbs', 11, 23, '&nbsp;د نېکانو اُميدونه په ښۀ څيزونو سره سر ته رسيږى، خو د بدکارانو اُميد صرف د غضب په طرف وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15724, 'Proverbs 11:24', 'Proverbs', 11, 24, '&nbsp;يو کس چې سخاوت کوى، نو نور هم مالداره کيږى، خو يو بل کس چې کنجوس وى نو نور به هم غريب شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15725, 'Proverbs 11:25', 'Proverbs', 11, 25, '&nbsp;يو سخى سړے به مالداره شى، او يو کس چې نور تازه کوى نو په خپله به هم تازه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15726, 'Proverbs 11:26', 'Proverbs', 11, 26, '&nbsp;خلق د هغه چا نه نفرت کوى څوک چې د ګرانۍ دپاره غله ذخيره کوى، خو د هغه چا خير غواړى څوک يې چې خرڅوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15727, 'Proverbs 11:27', 'Proverbs', 11, 27, '&nbsp;کۀ چرې تۀ خير غواړې نو تۀ به خير ومومې، خو شر هغه چا ته ورسيږى څوک يې چې لټون کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15728, 'Proverbs 11:28', 'Proverbs', 11, 28, '&nbsp;څوک چې په خپل دولت باندې اعتبار کوى نو هغه به پرېوځى، خو صادقان به د شنو پاڼو په شان تازه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15729, 'Proverbs 11:29', 'Proverbs', 11, 29, '&nbsp;څوک چې د خپل خاندان دپاره مصيبت پېدا کوى نو په ميراث کښې به ورته هوا پاتې شى، او کم عقل به د هوښيار نوکر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15730, 'Proverbs 11:30', 'Proverbs', 11, 30, '&nbsp;د صداقت مېوه د ژوندون ونه ده، خو هوښيار سړے زړونه ګټى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15731, 'Proverbs 11:31', 'Proverbs', 11, 31, '&nbsp;کۀ چرې صادقانو ته په زمکه د دوئ د کردار اجر ملاويږى، نو د بدعمله او ګناهګارانو به څۀ حال وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15732, 'Proverbs 12:1', 'Proverbs', 12, 1, '&nbsp;څوک چې اصلاح سره مينه لرى هغه د پوهې سره مينه لرى، خو چې څوک اصلاح نه نفرت کوى هغه کم عقل دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15733, 'Proverbs 12:2', 'Proverbs', 12, 2, '&nbsp;مالِک خُدائ د ښۀ سړى نه خوشحاله وى، خو مالِک خُدائ هغه کسان رد کوى چې د بدو منصوبې جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15734, 'Proverbs 12:3', 'Proverbs', 12, 3, '&nbsp;انسان د بدعملۍ په ذريعه قائم نۀ شى جوړېدے، خو د صادقانو جرړه به کله هم نۀ ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15735, 'Proverbs 12:4', 'Proverbs', 12, 4, '&nbsp;يوه پاک لمنه ښځه د خپل خاوند د سر تاج وى، خو يوه بې‌حيا ښځه د هغۀ په هډوکو کښې لکه د ناسور په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15736, 'Proverbs 12:5', 'Proverbs', 12, 5, '&nbsp;د صادقانو منصوبې د اِنصاف وى، خو د بدعملو په نصيحت کښې هم دوکه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15737, 'Proverbs 12:6', 'Proverbs', 12, 6, '&nbsp;د بدعمله خلقو خبرې د وينو توېدلو په طمع وى، خو د صادقانو خبرې د هغوئ ژوند بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15738, 'Proverbs 12:7', 'Proverbs', 12, 7, '&nbsp;بدعمله خلق مړۀ شى او فنا شى، خو د صادقانو خاندان کلک ولاړ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15739, 'Proverbs 12:8', 'Proverbs', 12, 8, '&nbsp;د سړى د خپل حِکمت په مطابق صِفت کيږى، خو د خراب ذهن لرونکى سپک کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15740, 'Proverbs 12:9', 'Proverbs', 12, 9, '&nbsp;دا ښۀ خبره ده چې انسان عام کس وى او نوکر يې وى، په ځائ د دې چې ځان ته څۀ وائى او د لوږې مرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15741, 'Proverbs 12:10', 'Proverbs', 12, 10, '&nbsp;صادق انسان د خپلو ځناورو د ضرورتونو خيال ساتى، خو د شرير ښۀ عمل هم د ظلم نه ډک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15742, 'Proverbs 12:11', 'Proverbs', 12, 11, '&nbsp;څوک چې په خپله زمکه کښې محنت کوى نو هغۀ سره به ډېر خوراک وى، خو څوک چې بې‌کاره منصوبو پسې ګرځى کم عقل دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15743, 'Proverbs 12:12', 'Proverbs', 12, 12, '&nbsp;بدعمله د بې‌دينه خلقو د لوټ شوى مال خواهش کوى، خو د صادقانو جرړې خوريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15744, 'Proverbs 12:13', 'Proverbs', 12, 13, '&nbsp;بد کاره سړے په خپلو خبرو کښې راګېر شى، خو صادق انسان د مصيبت نه بچ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15745, 'Proverbs 12:14', 'Proverbs', 12, 14, '&nbsp;انسان د خپلو شونډو په مېوه په ښۀ څيزونو مړيږى، لکه څنګه چې د هغۀ د لاسونو محنت دۀ له اجر ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15746, 'Proverbs 12:15', 'Proverbs', 12, 15, '&nbsp;کم عقلو ته خپل چال چلن ښۀ ښکارى، خو هوښيار سړے نصيحت ته غوږ نيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15747, 'Proverbs 12:16', 'Proverbs', 12, 16, '&nbsp;کم عقل انسان خپله غصه زر ښکاره کوى، خو هوښيار سړے بې‌عزتى هم نظر انداز کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15748, 'Proverbs 12:17', 'Proverbs', 12, 17, '&nbsp;رښتينے ګواه په صداقت سره ګواهى کوى، خو دروغژن ګواه دروغ وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15749, 'Proverbs 12:18', 'Proverbs', 12, 18, '&nbsp;د بې‌پرواهۍ خبرې د تُورې په شان غوڅول کوى، خو د عقلمند ژبه پرهرونو له شفا ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15750, 'Proverbs 12:19', 'Proverbs', 12, 19, '&nbsp;رښتينې خبرې د تل دپاره قائمې وى، خو د دروغو مزے لنډ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15751, 'Proverbs 12:20', 'Proverbs', 12, 20, '&nbsp;څوک چې د بدو منصوبې جوړوى نو د هغوئ په زړونو کښې دوکه وى، خو خوشحالى د هغه چا دپاره ده څوک چې امن راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15752, 'Proverbs 12:21', 'Proverbs', 12, 21, '&nbsp;صادقانو ته به هيڅ نقصان نۀ رسيږى، خو بدکاران به د مصيبت نه ډک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15753, 'Proverbs 12:22', 'Proverbs', 12, 22, '&nbsp;مالِک خُدائ د دروغژونو شونډو نه نفرت کوى، خو هغه د هر هغه چا نه خوشحاله وى څوک چې رښتينى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15754, 'Proverbs 12:23', 'Proverbs', 12, 23, '&nbsp;هوښيار خپل عِلم نۀ څرګندوى، خو کم عقل خلق خپل جهالت ښکاره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15755, 'Proverbs 12:24', 'Proverbs', 12, 24, '&nbsp;محنتى لاسونه به حکومت کوى، خو ناراستى به دې غلام کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15756, 'Proverbs 12:25', 'Proverbs', 12, 25, '&nbsp;اندېښمن زړۀ انسان لاندې کوى، خو نرمې او د ډاډ خبرې به هغه خوشحاله کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15757, 'Proverbs 12:26', 'Proverbs', 12, 26, '&nbsp;صادق انسان په دوستانه کښې احتياط کوى، خو د بدعمله چال چلن يې په غلطه لار بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15758, 'Proverbs 12:27', 'Proverbs', 12, 27, '&nbsp;ناراسته انسان خپل ښکار هم نۀ پخوى، خو محنتى انسان خپل مال دولت اضافه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15759, 'Proverbs 12:28', 'Proverbs', 12, 28, '&nbsp;د صداقت په لاره کښې ژوندون دے، په دغه لار کښې مرګ نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15760, 'Proverbs 13:1', 'Proverbs', 13, 1, '&nbsp;هوښيار زوئ د خپل پلار تربيت قبلوى، خو يو جاهله انسان ملامتيا ته غوږ نۀ نيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15761, 'Proverbs 13:2', 'Proverbs', 13, 2, '&nbsp;ښۀ انسان د خپلې خولې د مېوې نه د ښۀ څيزونو خوند اخلى، خو د غدارانو زړونه د ظلم کولو خواهش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15762, 'Proverbs 13:3', 'Proverbs', 13, 3, '&nbsp;څوک چې خپله ژبه په قابو کښې ساتى نو هغه خپل ژوند بچ کوى، خو چې څوک نۀ ساتى نو هغه به تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15763, 'Proverbs 13:4', 'Proverbs', 13, 4, '&nbsp;يو ناراسته کس ډېر څۀ غواړى خو څۀ ورته نۀ ملاويږى، خو د محنت کوونکى خواهش تر سره کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15764, 'Proverbs 13:5', 'Proverbs', 13, 5, '&nbsp;صادقان د دروغو نه نفرت کوى، خو د بدعملو کارونه د بې‌شرمۍ او بې‌عزتۍ سبب کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15765, 'Proverbs 13:6', 'Proverbs', 13, 6, '&nbsp;صداقت د نېکو خلقو لارې ساتى، خو شرارت بدعمله تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15766, 'Proverbs 13:7', 'Proverbs', 13, 7, '&nbsp;يو انسان خپل ځان داسې ښائى چې ګنې مالداره دے خو هيڅ هم نۀ لرى، خو يو بل انسان خپل ځان غريب ښائى، خو په اصل کښې ډېر زيات مالداره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15767, 'Proverbs 13:8', 'Proverbs', 13, 8, '&nbsp;د يو انسان مال دولت کېدے شى چې د هغۀ د ژوند فديه ورکړى، خو غريب انسان ته خو څوک دهمکى قدرې هم نۀ ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15768, 'Proverbs 13:9', 'Proverbs', 13, 9, '&nbsp;د صادقانو رڼا ډېره ځليږى، خو د بدعملو ډيوه په مړه کېدو ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15769, 'Proverbs 13:10', 'Proverbs', 13, 10, '&nbsp;غرور صرف لانجه پېدا کوى، خو حِکمت په هغوئ کښې وى څوک چې نصيحت منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15770, 'Proverbs 13:11', 'Proverbs', 13, 11, '&nbsp;حرام مال دولت به زر ختم شى، خو هغه څوک چې په ورو ورو مال جمع کوى هغوئ به دا اضافه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15771, 'Proverbs 13:12', 'Proverbs', 13, 12, '&nbsp;هغه اُميد چې په وخت پوره نۀ شى نو زړۀ بيماروى، خو کوم خواهش چې پوره کيږى نو هغه د ژوندون ونه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15772, 'Proverbs 13:13', 'Proverbs', 13, 13, '&nbsp;څوک چې ښۀ نصيحت ته سپک وګورى هغوئ به نقصانى شى، خو چې څوک د حُکم احترام کوى هغوئ ته به اجر مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15773, 'Proverbs 13:14', 'Proverbs', 13, 14, '&nbsp;د هوښيارانو تعليم د ژوند سرچينه وى، کوم چې انسان د مرګ د دامونو نه بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15774, 'Proverbs 13:15', 'Proverbs', 13, 15, '&nbsp;ښۀ پوهه د انسان دپاره عزت پېدا کوى، خو د بې‌ايمانانو لارې سختې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15775, 'Proverbs 13:16', 'Proverbs', 13, 16, '&nbsp;هر هوښيار سړے کار په حِکمت سره کوى، خو کم عقل د خپل جهالت اظهار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15776, 'Proverbs 13:17', 'Proverbs', 13, 17, '&nbsp;يو بدعمله پېغام وړونکے په مصيبت کښې راګېريږى، خو اعتمادى پېغام وړونکے د شفا باعث جوړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15777, 'Proverbs 13:18', 'Proverbs', 13, 18, '&nbsp;څوک چې تربيت نظر انداز کوى هغوئ به غريب او شرمنده شى، خو څوک چې نصيحت قبلوى هغه به عزتمند شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15778, 'Proverbs 13:19', 'Proverbs', 13, 19, '&nbsp;کوم خواهش چې پوره شى نو دا روح دپاره ډېر خوږ وى، خو کم عقل د بدکارۍ د اوړېدو نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15779, 'Proverbs 13:20', 'Proverbs', 13, 20, '&nbsp;څوک چې هوښيارانو سره ګرځى هغه هوښياريږى، خو د کم عقلو دوستانه نقصان ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15780, 'Proverbs 13:21', 'Proverbs', 13, 21, '&nbsp;مصيبت په ګناهګارو پسې روان وى، خو سوکالى د صادقانو اجر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15781, 'Proverbs 13:22', 'Proverbs', 13, 22, '&nbsp;يو ښۀ انسان د خپل نسل دپاره ميراث پرېږدى، خو د ګناهګارو مال دولت صادقانو ته حواله کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15782, 'Proverbs 13:23', 'Proverbs', 13, 23, '&nbsp;د غريب سړى پټى به ډېره غله پېدا کوى، خو بې‌اِنصافى به دا هر څۀ جارُو کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15783, 'Proverbs 13:24', 'Proverbs', 13, 24, '&nbsp;هغه څوک چې خپل زوئ نه د تربيت چوکه لرې ساتى هغه د هغۀ نه نفرت کوى، خو هغه څوک چې ورسره مينه کوى هغوئ يې په تربيت ورکولو کښې احتياط کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15784, 'Proverbs 13:25', 'Proverbs', 13, 25, '&nbsp;صادقان په مړه خېټه ډوډۍ خورى، خو د بدعملو خېټه اوږى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15785, 'Proverbs 14:1', 'Proverbs', 14, 1, '&nbsp;هوښياره ښځه خپل کور آبادوى، خو کم عقله ښځه يې په خپلو لاسونو ورانوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15786, 'Proverbs 14:2', 'Proverbs', 14, 2, '&nbsp;څوک چې په نېغه لار ځى هغه د مالِک خُدائ نه يريږى، خو چې څوک په غلطه لار ځى هغه يې سپک ګڼى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15787, 'Proverbs 14:3', 'Proverbs', 14, 3, '&nbsp;د کم عقل د خبرو نه يو ډنډا جوړه شى چې هغه وهى، خو د هوښيارانو خبرې هغوئ بچ ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15788, 'Proverbs 14:4', 'Proverbs', 14, 4, '&nbsp;چرته چې غوَيى نۀ وى هلته اخور خالى وى، خو د غوَيى د طاقت په وجه ډېر فصل پېدا کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15789, 'Proverbs 14:5', 'Proverbs', 14, 5, '&nbsp;يو رښتينے ګواه دروغ نۀ وائى، خو يو دروغژن ګواه ډوزې وولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15790, 'Proverbs 14:6', 'Proverbs', 14, 6, '&nbsp;مسخره کوونکى حِکمت لټوى او هيڅ نۀ مومى، خو حِکمت آسانۍ سره تميز دارو له راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15791, 'Proverbs 14:7', 'Proverbs', 14, 7, '&nbsp;د کم عقلو نه لرې اوسه، ځکه چې تۀ به د هغۀ د خولې نه حِکمت حاصل نۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15792, 'Proverbs 14:8', 'Proverbs', 14, 8, '&nbsp;د هوښيار حِکمت دا دے چې خپلو لارو ته سوچ وکړى، خو د کم عقل کم عقلتوب هغه بې‌لارې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15793, 'Proverbs 14:9', 'Proverbs', 14, 9, '&nbsp;کم عقل خپلې د ګناه د تاوان د نذرانې پورې خندا کوى، خو صادقان د مالِک خُدائ رضا حاصلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15794, 'Proverbs 14:10', 'Proverbs', 14, 10, '&nbsp;هر څوک په خپل خفګان ښۀ پوهيږى، او نور هيڅوک د هغۀ په خوشحالۍ نۀ پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15795, 'Proverbs 14:11', 'Proverbs', 14, 11, '&nbsp;د بدعمله کور به تباه شى، خو د صادقانو خېمه به آباده شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15796, 'Proverbs 14:12', 'Proverbs', 14, 12, '&nbsp;د هر کس په وړاندې يوه لار وى چې هغۀ ته ښۀ ښکارى خو په آخر کښې د دې خاتمه مرګ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15797, 'Proverbs 14:13', 'Proverbs', 14, 13, '&nbsp;په خندا کښې هم زړۀ خفه کيږى او خوشحالۍ نه وروستو هم خفګان پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15798, 'Proverbs 14:14', 'Proverbs', 14, 14, '&nbsp;بې‌ايمانان چې د څۀ حقدار وى هغه به ورته مِلاو شى او نېک انسان ته به د دۀ د اعمالو په مطابق اجر مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15799, 'Proverbs 14:15', 'Proverbs', 14, 15, '&nbsp;يو ساده سړے په هر څۀ باندې يقين کوى، خو هوښيار په هر قدم اوچتولو سوچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15800, 'Proverbs 14:16', 'Proverbs', 14, 16, '&nbsp;هوښيار احتياط کوى او د غلط کار نه ځان بچ ساتى، خو کم عقل په خپل ځان غاوره وى او د هيڅ پرواه نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');